CREATE FUNCTION espia() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE NOTICE '% | % % % | NEW=% OLD=%',
    TG_NAME, TG_WHEN, TG_LEVEL, TG_OP, NEW, OLD;
  RETURN coalesce(NEW, OLD);
END $$;
