CREATE FUNCTION limpiar_cliente() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.nombre = 'PRUEBA' THEN
    RAISE NOTICE 'Fila de prueba descartada: %', NEW.rut;
