CREATE FUNCTION validar_item() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  p productos%ROWTYPE;
BEGIN
  SELECT * INTO p FROM productos WHERE id = NEW.producto_id;
  IF NOT p.activo THEN
    RAISE EXCEPTION 'El producto % está descontinuado', p.sku
      USING ERRCODE = 'check_violation';
  END IF;
  IF p.stock < NEW.cantidad THEN
    RAISE EXCEPTION 'Stock insuficiente para %: pides %, quedan %', p.sku, NEW.cantidad, p.stock
      USING ERRCODE = 'check_violation', HINT = 'Revisa el stock antes de vender.';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER pedido_items_validar
  BEFORE INSERT ON pedido_items
  FOR EACH ROW EXECUTE FUNCTION validar_item();
CREATE FUNCTION mover_stock() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE productos SET stock = stock - NEW.cantidad WHERE id = NEW.producto_id;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE productos SET stock = stock + OLD.cantidad WHERE id = OLD.producto_id;
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER pedido_items_mover_stock
  AFTER INSERT OR DELETE ON pedido_items
  FOR EACH ROW EXECUTE FUNCTION mover_stock();
