CREATE FUNCTION registrar_cambios_precio() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO cambios_precio (producto_id, precio_antes, precio_despues)
  SELECT v.id, v.precio, n.precio
  FROM viejos AS v
  JOIN nuevos AS n ON n.id = v.id
  WHERE v.precio IS DISTINCT FROM n.precio;
  RAISE NOTICE 'Sentencia con % filas; % cambiaron de precio',
    (SELECT count(*) FROM nuevos),
    (SELECT count(*) FROM viejos AS v JOIN nuevos AS n USING (id) WHERE v.precio <> n.precio);
  RETURN NULL;
END $$;
CREATE TRIGGER productos_cambios_precio
  AFTER UPDATE ON productos
  REFERENCING OLD TABLE AS viejos NEW TABLE AS nuevos
  FOR EACH STATEMENT
  EXECUTE FUNCTION registrar_cambios_precio();
