CREATE FUNCTION desactivar_sin_stock() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE NOTICE 'nivel %: % (stock %, activo %)', pg_trigger_depth(), NEW.sku, NEW.stock, NEW.activo;
  IF pg_trigger_depth() > 4 THEN
    RAISE EXCEPTION 'Recursión sin fin: el trigger ya va en el nivel %', pg_trigger_depth();
  END IF;
  IF NEW.stock = 0 THEN
    UPDATE productos SET activo = false WHERE id = NEW.id;
  END IF;
  RETURN NULL;
END $$;
