CREATE FUNCTION catalogo_escribir() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  v_categoria integer;
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    SELECT id INTO v_categoria FROM categorias WHERE nombre = NEW.categoria;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'La categoría «%» no existe', NEW.categoria
        USING ERRCODE = 'foreign_key_violation',
              HINT = 'Revisa SELECT nombre FROM categorias.';
    END IF;
  END IF;
  IF TG_OP = 'INSERT' THEN
    INSERT INTO productos (sku, nombre, categoria_id, precio, costo, stock, creado_en)
    VALUES (NEW.sku, NEW.nombre, v_categoria, NEW.precio,
            round(NEW.precio * 0.6), NEW.stock, current_date);
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    UPDATE productos
    SET sku = NEW.sku, nombre = NEW.nombre, categoria_id = v_categoria,
        precio = NEW.precio, stock = NEW.stock
    WHERE sku = OLD.sku;
    RETURN NEW;
  ELSE
    UPDATE productos SET activo = false WHERE sku = OLD.sku;
    RETURN OLD;
  END IF;
END $$;
CREATE TRIGGER catalogo_escribir
  INSTEAD OF INSERT OR UPDATE OR DELETE ON catalogo
  FOR EACH ROW EXECUTE FUNCTION catalogo_escribir();
