CREATE FUNCTION impedir_drop() RETURNS event_trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF current_setting('app.permitir_drop', true) IS DISTINCT FROM 'si' THEN
    RAISE EXCEPTION '% está bloqueado en esta base', TG_TAG
      USING HINT = 'Si de verdad quieres hacerlo: SET app.permitir_drop = ''si''';
