CREATE FUNCTION informar_borrados() RETURNS event_trigger
LANGUAGE plpgsql AS $$
DECLARE
  o record;
BEGIN
  FOR o IN SELECT * FROM pg_event_trigger_dropped_objects() LOOP
    RAISE NOTICE '% borró: % % (original: %)', TG_TAG, o.object_type, o.object_identity, o.original;
  END LOOP;
END $$;
