CREATE FUNCTION proteger_tablas() RETURNS event_trigger
LANGUAGE plpgsql AS $$
DECLARE
  o record;
BEGIN
  IF current_setting('app.permitir_drop', true) IS NOT DISTINCT FROM 'si' THEN
