  FOR o IN SELECT * FROM pg_event_trigger_dropped_objects()
           WHERE object_type = 'table' AND NOT is_temporary AND schema_name <> 'borrador'
  LOOP
    RAISE EXCEPTION 'Borrar la tabla % está prohibido', o.object_identity
      USING HINT = 'Si es intencional: SET app.permitir_drop = ''si''';
  END LOOP;
END $$;
