CREATE FUNCTION impedir_rebaja() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.sueldo < OLD.sueldo THEN
    RAISE EXCEPTION 'No se permiten rebajas de sueldo: empleado %, de % a %', OLD.id, OLD.sueldo, NEW.sueldo;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER empleados_sin_rebajas
  BEFORE UPDATE OF sueldo ON empleados
  FOR EACH ROW EXECUTE FUNCTION impedir_rebaja();
CREATE FUNCTION registrar_sueldo() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO historial_sueldos (empleado_id, desde, sueldo)
  VALUES (NEW.id, current_date, NEW.sueldo)
  ON CONFLICT (empleado_id, desde) DO UPDATE SET sueldo = EXCLUDED.sueldo;
  INSERT INTO auditoria_sueldos (empleado_id, sueldo_antes, sueldo_despues, usuario, momento)
  VALUES (NEW.id, OLD.sueldo, NEW.sueldo, current_user, now());
  RETURN NULL;
END $$;
CREATE TRIGGER empleados_registrar_sueldo
  AFTER UPDATE OF sueldo ON empleados
  FOR EACH ROW
  WHEN (OLD.sueldo IS DISTINCT FROM NEW.sueldo)
  EXECUTE FUNCTION registrar_sueldo();

