CREATE FUNCTION mover_stock_item() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE productos SET stock = stock - NEW.cantidad WHERE id = NEW.producto_id;
    INSERT INTO movimientos_stock (producto_id, cantidad, motivo, pedido_id)
    VALUES (NEW.producto_id, -NEW.cantidad, 'venta', NEW.pedido_id);
  ELSIF TG_OP = 'UPDATE' THEN
    UPDATE productos SET stock = stock - (NEW.cantidad - OLD.cantidad) WHERE id = NEW.producto_id;
    INSERT INTO movimientos_stock (producto_id, cantidad, motivo, pedido_id)
    VALUES (NEW.producto_id, OLD.cantidad - NEW.cantidad, 'ajuste', NEW.pedido_id);
  ELSIF NOT EXISTS (SELECT 1 FROM pedidos WHERE id = OLD.pedido_id AND estado = 'cancelado') THEN
    UPDATE productos SET stock = stock + OLD.cantidad WHERE id = OLD.producto_id;
    INSERT INTO movimientos_stock (producto_id, cantidad, motivo, pedido_id)
    VALUES (OLD.producto_id, OLD.cantidad, 'devolucion', OLD.pedido_id);
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER pedido_items_stock
  AFTER INSERT OR DELETE ON pedido_items
  FOR EACH ROW EXECUTE FUNCTION mover_stock_item();
CREATE TRIGGER pedido_items_ajuste
  AFTER UPDATE OF cantidad ON pedido_items
  FOR EACH ROW WHEN (OLD.cantidad IS DISTINCT FROM NEW.cantidad)
  EXECUTE FUNCTION mover_stock_item();
CREATE FUNCTION anular_pedido() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  UPDATE productos AS p
  SET stock = p.stock + i.cantidad
  FROM pedido_items AS i
  WHERE i.pedido_id = NEW.id AND p.id = i.producto_id;
  INSERT INTO movimientos_stock (producto_id, cantidad, motivo, pedido_id)
  SELECT producto_id, cantidad, 'anulacion', pedido_id
  FROM pedido_items
  WHERE pedido_id = NEW.id;
  RETURN NULL;
END $$;
CREATE TRIGGER pedidos_anular
  AFTER UPDATE OF estado ON pedidos
  FOR EACH ROW
  WHEN (NEW.estado = 'cancelado' AND OLD.estado IS DISTINCT FROM 'cancelado')
  EXECUTE FUNCTION anular_pedido();

